.filter-row { display: flex; gap: 1rem; justify-content: space-between; align-items: center; margin: 2rem 0; flex-wrap: wrap; }
select, input[type='email'] { background: oklch(100% 0 0 / .06); color: white; border: 1px solid var(--line); border-radius: 999px; padding: 1rem 1.1rem; min-height: 3.2rem; }
