.faq-answer { max-height: 0; overflow: hidden; transition: max-height .28s ease; }
.faq-answer p { padding: 0 1.35rem 1.35rem; }
.faq-item.open .faq-answer { max-height: 220px; }
.faq-item.open .faq-question span { color: var(--red); }

.newsletter { border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); background: oklch(100% 0 0 / .035); }
.newsletter form { display: flex; gap: .8rem; margin-top: 1.5rem; max-width: 680px; }
.newsletter input { flex: 1; min-width: 0; }
.form-message { margin-top: .8rem; min-height: 1.4rem; color: var(--red-soft); font-weight: 800; }
.form-message.success { color: oklch(78% 0.16 145); }
.form-message.error { color: var(--red-soft); }

.footer { padding: 4rem clamp(1rem, 4vw, 4rem) 2rem; background: oklch(4% 0.008 28); border-top: 1px solid var(--line); }
.footer-grid { display: grid; grid-template-columns: 1.4fr repeat(3, 1fr) 1.1fr; gap: 2rem; }
.footer h4 { font-size: .8rem; color: white; letter-spacing: .18em; text-transform: uppercase; margin: 0 0 1rem; }
.footer a, .footer button { display: block; margin: .55rem 0; color: var(--muted); background: none; border: 0; padding: 0; text-align: left; }
.country { position: relative; }
.country-menu { display: none; position: absolute; bottom: calc(100% + .8rem); left: 0; min-width: 190px; padding: .8rem; background: var(--panel-2); border: 1px solid var(--line); border-radius: 16px; box-shadow: var(--shadow); }
