  .menu-toggle { display: block; }
  .nav.open { align-items: flex-start; }
  .nav.open .nav-links, .nav.open .utility { display: flex; position: absolute; left: 1rem; right: 1rem; top: calc(100% + .5rem); flex-direction: column; align-items: stretch; padding: 1rem; background: var(--panel); border: 1px solid var(--line); border-radius: 22px; }
